def find_anagram_indices(s, p):
    from collections import Counter
    n, k = len(s), len(p)
    if k > n:
        return []
    need = Counter(p)
    window = Counter(s[:k])
    result = []
    if window == need:
        result.append(0)
    for i in range(k, n):
        window[s[i]] += 1
        left = s[i - k]
        window[left] -= 1
        if window[left] == 0:
            del window[left]
        if window == need:
            result.append(i - k + 1)
    return result
